import React, { createContext, useState, ReactNode } from 'react';

interface GlobalContextType {
  keysPressed: string; 
  number: number;
  guesses: string[];
  setKeysPressed: (keys: string | ((prevKeys: string) => string)) => void; // Allow both string and function
  addGuess: (guess: number) => void;
  setGuesses: (guesses: string[]) => void;
}

const GlobalContext = createContext<GlobalContextType | undefined>(undefined);

interface GlobalProviderProps {
  children: ReactNode;
}

export const GlobalProvider: React.FC<GlobalProviderProps> = ({ children }) => {
  const [keysPressed, setKeysPressed] = useState<string>(''); 
  const [number, setNumber] = useState<number>(0);
  const [guesses, setGuesses] = useState<string[]>(Array(6).fill(''));

  const addGuess = (guess: number) => {
    setGuesses(prevGuesses => {
      const newGuesses = [...prevGuesses];
      const index = prevGuesses.findIndex(g => g === '');
      if (index !== -1) {
        newGuesses[index] = String(guess);
      }
      return newGuesses;
    });
  };

  return (
    <GlobalContext.Provider value={{ keysPressed, number, guesses, setKeysPressed, addGuess, setGuesses }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobalContext = () => {
  const context = React.useContext(GlobalContext);
  if (!context) {
    throw new Error('useGlobalContext must be used within a GlobalProvider');
  }
  return context;
};
